+            <LuSettings />
+            <Heading size="md">{translate("variables.backendsOrder")}</Heading>
+          </HStack>
+          <Dialog.CloseTrigger />
+        </Dialog.Header>
+        <Dialog.Body>
+          {Boolean(error) ? <ErrorAlert error={error} /> : null}
